class Curve(CurveType):
    """
    A curve is a 1-dimensional primitive.

    Curves are continuous, connected, and have a measurable length in terms of the coordinate system. A curve is
    composed of one or more curve segments. Each curve segment within a curve may be defined using a different
    interpolation method. The curve segments are connected to one another, with the end point of each segment except
    the last being the start point of the next segment in the segment list. The orientation of the curve is
    positive. The element segments encapsulates the segments of the curve.
    """

    class Meta:
        namespace = "http://www.opengis.net/gml/3.2"

    model_config = ConfigDict(defer_build=True)


class PolyhedralSurface(SurfaceType):
    """
    A polyhedral surface is a surface composed of polygon patches connected along their common boundary curves.

    This differs from the surface type only in the restriction on the types of surface patches acceptable.
    polygonPatches encapsulates the polygon patches of the polyhedral surface.
    """

    class Meta:
        namespace = "http://www.opengis.net/gml/3.2"

    model_config = ConfigDict(defer_build=True)


class Surface(SurfaceType):
    """
    A Surface is a 2-dimensional primitive and is composed of one or more surface patches as specified in ISO
    19107:2003, 6.3.17.1.

    The surface patches are connected to one another. patches encapsulates the patches of the surface.
    """

    class Meta:
        namespace = "http://www.opengis.net/gml/3.2"

    model_config = ConfigDict(defer_build=True)


